(function(){document.addEventListener('DOMContentLoaded',function(){if(document.querySelector('header.ww2-top')){document.querySelectorAll('.topbar,.brand-bar,.search-bar,nav.nav,header.topbar').forEach(function(n){if(!n.closest('.ww2-top')&&!n.closest('.ww2-main-nav')) n.remove();});var tops=[...document.querySelectorAll('header.ww2-top')];if(tops.length>1){tops.slice(1).forEach(n=>n.remove());}var navs=[...document.querySelectorAll('nav.ww2-main-nav')];if(navs.length>1){navs.slice(1).forEach(n=>n.remove());}}});})();
